`timescale 1ns/1ps
module advanced_top #(
    parameter integer CLK_HZ=66000000,
    parameter integer BAUD=115200,
    parameter ROM_FILE="",
    parameter RAM_FILE=""
)(input wire sys_clk,rst_n,uart_rx,output wire uart_tx,output wire[3:0]led);
    wire cpu_clk,pll_locked;
    cpu_clock #(.FB_DIV(44),.OUT_DIV(18)) u_cpu_clock(
      .ref_clk(sys_clk),.reset_n(rst_n),.clk(cpu_clk),.locked(pll_locked));
    wire run_n=rst_n && pll_locked;
    reg[7:0]por=8'hff;
    always @(posedge cpu_clk or negedge run_n)
      if(!run_n)por<=8'hff;else por<={por[6:0],1'b0};
    wire rst=por[7];
    wire halted;wire[31:0]result,gpo,goe;
    reg[25:0]heartbeat;
    always @(posedge cpu_clk)if(rst)heartbeat<=0;else heartbeat<=heartbeat+1'b1;
    wire[3:0]status={result[8],heartbeat[25],halted,result==1};
    assign led=(status & ~goe[3:0]) | (gpo[3:0]&goe[3:0]);
    advanced_soc #(.CLK_HZ(CLK_HZ),.BAUD(BAUD),.ROM_FILE(ROM_FILE),.RAM_FILE(RAM_FILE)) u_soc(
      .clk(cpu_clk),.rst(rst),.uart_rx(uart_rx),.uart_tx(uart_tx),.gpio_in(32'b0),.gpio_out(gpo),.gpio_oe(goe),
      .halted(halted),.test_result(result),.debug_pc(),.trap_cause(),.trap_pc(),.trap_value(),
      .commit_valid(),.commit_pc(),.commit_inst(),.commit_rd_we(),.commit_rd(),.commit_wdata());
endmodule

module advanced_soc #(
    parameter integer CLK_HZ=27000000, BAUD=115200,
    parameter integer CACHE_ENABLE=1,
    parameter ROM_FILE="", RAM_FILE=""
)(
    input wire clk,rst,uart_rx,
    output wire uart_tx,
    input wire [31:0] gpio_in,
    output wire [31:0] gpio_out,gpio_oe,
    output wire halted,
    output wire [31:0] test_result,debug_pc,trap_cause,trap_pc,trap_value,
    output wire commit_valid,
    output wire [31:0] commit_pc,commit_inst,
    output wire commit_rd_we,
    output wire [4:0] commit_rd,
    output wire [31:0] commit_wdata
);
    wire iv,ir,ie,dv,dw,dr,de,fv,fr,fiv,fir;
    wire [31:0] ia,idata,da,wd,rd;
    wire [2:0] df;
    wire irq_timer,irq_software,irq_gpio,irq_uart;
    wire data_preview_valid;
    wire [31:0] data_preview_addr;
    cpu_core #(.BRANCH_PREDICT(1),.BTB_INDEX_BITS(7),.PRIVILEGED(1),
               .DIRECT_JUMP_PREDICT(1),.RETURN_PREDICT(1),.ZMMUL(1)) u_core(
      .clk(clk),.rst(rst),.imem_valid(iv),.imem_addr(ia),.imem_ready(ir),.imem_rdata(idata),.imem_error(ie),
      .dmem_valid(dv),.dmem_write(dw),.dmem_addr(da),.dmem_wdata(wd),.dmem_funct3(df),
      .dmem_ready(dr),.dmem_rdata(rd),.dmem_error(de),.fence_valid(fv),.fence_ready(fr),
      .fence_i_valid(fiv),.fence_i_ready(fir),
      .irq_timer(irq_timer),.irq_software(irq_software),.irq_external(irq_gpio|irq_uart),
      .halted(halted),
      .debug_pc(debug_pc),.trap_cause(trap_cause),.trap_pc(trap_pc),.trap_value(trap_value),
      .commit_valid(commit_valid),.commit_pc(commit_pc),.commit_inst(commit_inst),
      .commit_rd_we(commit_rd_we),.commit_rd(commit_rd),.commit_wdata(commit_wdata),
      .redirect_valid(),.redirect_target(),
      .dmem_preview_valid(data_preview_valid),.dmem_preview_addr(data_preview_addr));
    wire biv,bir,bie,biw;
    wire [31:0] bia,biwd,bird;
    wire [2:0] bif;
    wire bdr,bde,bdv,bdw;
    wire [31:0] bda,bdwd,bdrd;
    wire [2:0] bdf;
    wire ibusy,dbusy,idone;
    wire [31:0] ihit,imiss,ifill,iwrites,dhit,dmiss,dfill,dwrites;
    reg fi_started,fi_done;
    wire invalidate_i=fiv && !fi_started;
    always @(posedge clk) begin
      if(rst || !fiv) begin fi_started<=0;fi_done<=0;end
      else begin
        if(!fi_started)fi_started<=1;
        if(idone)fi_done<=1;
      end
    end
    assign fir=CACHE_ENABLE ? fi_done : 1'b1;
    wire data_ram=da[31:16]==0;
    wire periph_select=da[31:16]==16'h0200 || da[31:8]==24'h100002;
    wire stats_select=da>=32'h10000300 && da<=32'h1000031c;
    wire direct_bus=dv && !data_ram && !periph_select && !stats_select;
    wire cr,ce;wire[31:0]cd;
    generate if(CACHE_ENABLE)begin:g_cache
      cache_2way #(.READ_ONLY(1),.SETS(256),.ADDR_WIDTH(16)) u_icache(
       .clk(clk),.rst(rst),.req_valid(iv),.req_write(1'b0),.req_addr(ia),.req_wdata(32'b0),.req_funct3(3'd2),
       .ready(ir),.error(ie),.rdata(idata),.bf_req_valid(biv),.bf_req_write(biw),.bf_req_addr(bia),.bf_req_wdata(biwd),.bf_req_funct3(bif),
       .bf_ready(bir),.bf_error(bie),.bf_rdata(bird),.invalidate(invalidate_i),.invalidate_done(idone),.busy(ibusy),
       .hit_count(ihit),.miss_count(imiss),.refill_word_count(ifill),.backend_write_count(iwrites));
      cache_2way #(.READ_ONLY(0),.SETS(128),.ADDR_WIDTH(16),.DATA_PREVIEW(1),.WRITE_RESPONSE_FORWARD(1)) u_dcache(
       .clk(clk),.rst(rst),.req_valid(dv && data_ram),.req_write(dw),.req_addr(da),.req_wdata(wd),.req_funct3(df),
       .ready(cr),.error(ce),.rdata(cd),.bf_req_valid(bdv),.bf_req_write(bdw),.bf_req_addr(bda),.bf_req_wdata(bdwd),.bf_req_funct3(bdf),
       .bf_ready(bdr),.bf_error(bde),.bf_rdata(bdrd),.invalidate(1'b0),.invalidate_done(),.busy(dbusy),
       .preview_valid(data_preview_valid && data_preview_addr[31:16]==0),.preview_addr(data_preview_addr),
       .hit_count(dhit),.miss_count(dmiss),.refill_word_count(dfill),.backend_write_count(dwrites));
    end else begin:g_no_cache
      assign biv=iv;assign bia=ia;assign biw=0;assign biwd=0;assign bif=2;
      assign ir=bir;assign ie=bie;assign idata=bird;
      assign bdv=dv && data_ram;assign bda=da;assign bdw=dw;assign bdwd=wd;assign bdf=df;
      assign cr=bdr;assign ce=bde;assign cd=bdrd;
      assign ibusy=0;assign dbusy=0;assign idone=0;
      assign ihit=0;assign imiss=0;assign ifill=0;assign iwrites=0;
      assign dhit=0;assign dmiss=0;assign dfill=0;assign dwrites=0;
    end endgenerate
    // The sequential line-fill request stream reuses the ROM's clocked
    // prefetch port: consecutive acknowledged words need no controller gap.
    rom_sync #(.ADDR_WIDTH(16),.PREFETCH(1),.INIT_FILE(ROM_FILE)) u_rom(
      .clk(clk),.rst(rst),.req_valid(biv),.addr(bia),.ready(bir),.error(bie),.inst(bird));
    wire bus_valid=bdv|direct_bus;
    wire bus_write=bdv ? bdw : dw;
    wire [31:0] bus_addr=bdv ? bda : da;
    wire [31:0] bus_wdata=bdv ? bdwd : wd;
    wire [2:0] bus_size=bdv ? bdf : df;
    wire bus_ready,bus_error;wire[31:0]bus_rdata;
    data_bus #(.CLK_HZ(CLK_HZ),.BAUD(BAUD),.RAM_ADDR_WIDTH(16),.SYNC_RAM(1),.AI_ENABLE(1),.RAM_FILE(RAM_FILE)) u_bus(
      .clk(clk),.rst(rst),.req_valid(bus_valid),.req_write(bus_write),.req_addr(bus_addr),.req_wdata(bus_wdata),.req_funct3(bus_size),
      .req_ready(bus_ready),.rsp_rdata(bus_rdata),.rsp_error(bus_error),.fence_ready(fr),
      .uart_rx_i(uart_rx),.uart_tx_o(uart_tx),.test_result(test_result),.irq_uart(irq_uart));
    assign bdr=bus_ready;assign bde=bus_error;assign bdrd=bus_rdata;
    wire pr,pe;wire[31:0]pd;
    soc_peripherals u_peripherals(
      .clk(clk),.rst(rst),.req_valid(dv && periph_select),.req_write(dw),.req_addr(da),.req_wdata(wd),.req_funct3(df),
      .ready(pr),.error(pe),.rdata(pd),.gpio_in(gpio_in),.gpio_out(gpio_out),.gpio_oe(gpio_oe),
      .irq_timer(irq_timer),.irq_software(irq_software),.irq_gpio(irq_gpio));
    reg [31:0] stats;
    always @(*) case(da[4:2])
      0:stats=ihit;1:stats=imiss;2:stats=ifill;3:stats=iwrites;
      4:stats=dhit;5:stats=dmiss;6:stats=dfill;default:stats=dwrites;
    endcase
    assign dr=data_ram ? cr : periph_select ? pr : stats_select ? !rst : bus_ready;
    assign de=data_ram ? ce : periph_select ? pe : stats_select ? (dw || df!=2 || da[1:0]!=0) : bus_error;
    assign rd=data_ram ? cd : periph_select ? pd : stats_select ? stats : bus_rdata;
endmodule

module alu(
input [31:0]rdata1,
input [31:0]rdata2,
//R 指令
input wire  SLLI,
input wire  SRLI,
input wire  SRAI,
input wire  ADD,
input wire  SUB,
input wire  SLL,
input wire  SLT,
input wire  SLTU,
input wire  XOR,
input wire  SRL,
input wire  SRA,
input wire  OR,
input wire  AND,
//I 指令
input wire  JALR,
input wire  LB,
input wire  LH,
input wire  LW,
input wire  LBU,
input wire  LHU,
input wire  ADDI,
input wire  SLTI,
input wire  SLTIU,
input wire  XORI,
input wire  ORI,
input wire  ANDI,
//S 指令
input wire  SB,
input wire  SH,
input wire  SW,
//B 指令
input wire  BEQ,
input wire  BNE,
input wire  BLT,
input wire  BGE,
input wire  BLTU,
input wire  BGEU,
//U 指令
input wire  LUI,
input wire  AUIPC,

//J 指令
input wire  JAL,
//
input wire  FENCE,
input wire  FENCETSO,
input wire  PAUSE,
input wire  ECALL,
input wire  EBREAK,
input wire [31:0] imm_i,
input wire [31:0] imm_s,
input wire [31:0] imm_b,
input wire [31:0] imm_u,
input wire [31:0] imm_j,
input  [31:0] pc,

output reg  [31:0] mem_addr,
output reg         branch_taken,
output reg  [31:0] branch_target,
output reg [31:0] wdata
    );
    // Control bits come from the mutually-exclusive instruction decoder.
    wire unsigned_less = rdata1 < rdata2;
    wire signed_less = (rdata1[31] != rdata2[31]) ? rdata1[31] : unsigned_less;
    // Keep EX branch resolution independent of the arithmetic result priority chain.
    always @(*) begin
        branch_taken = JAL || JALR || (BEQ && rdata1==rdata2) ||
            (BNE && rdata1!=rdata2) || (BLT && signed_less) ||
            (BGE && !signed_less) || (BLTU && unsigned_less) || (BGEU && !unsigned_less);
        branch_target = 32'd0;
        if(JALR) branch_target=(rdata1+imm_i) & 32'hffff_fffe;
        else if(JAL) branch_target=pc+imm_j;
        else if(BEQ || BNE || BLT || BGE || BLTU || BGEU) branch_target=pc+imm_b;
    end
    always @(*) begin
        // 默认值：确保所有输出在任何情况下都有赋值
        wdata         = 32'd0;
        mem_addr      = 32'd0;

        
        // 加法
        if (ADD ) begin
            wdata = rdata1 + rdata2;
        end
        //减法
        else if (SUB) begin
            wdata = rdata1 - rdata2;
        end
        //加立即数
        else if (ADDI) begin
            wdata = rdata1 + imm_i;
        end
        
        // 按位与逻辑
        else if (AND ) begin
            wdata = rdata1 & rdata2;
        end
        else if (ANDI ) begin
            wdata = rdata1 & imm_i;
        end
        // 按位或逻辑
        else if (OR ) begin
            wdata = rdata1 | rdata2;
        end
        else if (ORI ) begin
            wdata = rdata1 | imm_i;
        end
        // 按位异或逻辑
        else if (XOR ) begin
            wdata = rdata1 ^ rdata2;
        end
        else if (XORI ) begin
            wdata = rdata1 ^ imm_i;
        end
        
        // 逻辑左移，补0
        else if (SLL ) begin
            wdata = rdata1 << rdata2[4:0];
        end
        else if (SLLI ) begin
            wdata = rdata1 << imm_i[4:0];
        end
        //逻辑右移，补0
        else if (SRL ) begin
            wdata = rdata1 >> rdata2[4:0];
        end
        else if (SRLI ) begin
            wdata = rdata1 >> imm_i[4:0];
        end
        //算术右移，按最高位补
        else if (SRA ) begin
            wdata = $signed(rdata1) >>> rdata2[4:0];
        end
        else if (SRAI) begin
            wdata = $signed(rdata1) >>> imm_i[4:0] ;
        end
       
        // 有符号比较
        else if (SLT ) begin
            wdata =signed_less? 32'd1 : 32'd0;
        end
        else if (SLTI ) begin
            wdata =($signed(rdata1) <$signed(imm_i))? 32'd1 : 32'd0;
        end
        
        // 无符号比较
        else if (SLTU ) begin
            wdata =unsigned_less? 32'd1 : 32'd0;
        end
        else if (SLTIU ) begin
            wdata =(rdata1 < imm_i)? 32'd1 : 32'd0;
        end
        
        // U 型指令
        else if (LUI) begin
            wdata = imm_u;
        end
        else if (AUIPC) begin
            wdata = pc + imm_u;
        end

        // 加载：这里只计算地址
        //LW读32位
        //LB读8位
        //LH读16位
        else if (LB || LH || LW || LBU || LHU) begin
            mem_addr = rdata1 + imm_i;
        end

        // 存储：这里只计算地址
        //SW读32位
        //SB读8位
        //SH读16位
        else if (SB || SH || SW) begin
            mem_addr = rdata1 + imm_s;
        end

        // Both jump instructions write the link address.
        else if (JAL || JALR) begin
            wdata = pc + 32'd4;
        end

        // FENCE、FENCETSO、PAUSE、ECALL、EBREAK
        // 不在本模块中处理，输出保持默认值。
        // 它们的控制行为必须由外部逻辑实现。
    end
endmodule

module cache_2way #(
    parameter integer READ_ONLY = 0,
    parameter integer SETS = 16,
    parameter integer LINE_WORDS = 4,
    parameter integer ADDR_WIDTH = 16,
    // Read-only sequential lookahead uses the existing clocked data ports.
    // Both switches may be disabled for a cycle-identical baseline.
    parameter integer READ_LOOKAHEAD = READ_ONLY,
    parameter integer REFILL_FORWARD = 1,
    parameter integer DATA_PREVIEW = 0,
    parameter integer WRITE_RESPONSE_FORWARD = 0
)(
    input wire clk, rst,
    input wire req_valid, req_write,
    input wire [31:0] req_addr, req_wdata,
    input wire [2:0] req_funct3,
    output wire ready, error,
    output wire [31:0] rdata,

    output wire bf_req_valid, bf_req_write,
    output wire [31:0] bf_req_addr, bf_req_wdata,
    output wire [2:0] bf_req_funct3,
    input wire bf_ready, bf_error,
    input wire [31:0] bf_rdata,

    // A level request is accepted once until it goes low again. Requests
    // arriving during a transaction are latched and serviced after completion.
    input wire invalidate,
    output reg invalidate_done,
    output wire busy,
    output reg [31:0] hit_count, miss_count,
    output reg [31:0] refill_word_count, backend_write_count,
    input wire preview_valid,
    input wire [31:0] preview_addr
);
    localparam integer SET_BITS = $clog2(SETS);
    localparam integer WORD_BITS = $clog2(LINE_WORDS);
    localparam integer LINE_BITS = WORD_BITS + 2;
    localparam integer ARRAY_WORDS = SETS * LINE_WORDS;
    // High address bits are rejected before any tag lookup can complete or
    // refill can install a line. Store only the architecturally reachable tag.
    localparam integer TAG_BITS = ADDR_WIDTH>LINE_BITS+SET_BITS ? ADDR_WIDTH-LINE_BITS-SET_BITS : 1;
    localparam [3:0] S_IDLE=0, S_READ=1, S_ACCESS=2,
                     S_REFILL=3, S_WRITE=4, S_RESP=5, S_INVALIDATE=6;

    reg [3:0] state;
    reg [SETS-1:0] valid0, valid1, lru_victim;
    reg [TAG_BITS-1:0] tags0 [0:SETS-1];
    reg [TAG_BITS-1:0] tags1 [0:SETS-1];
    // Data and read registers are deliberately not reset. Reads are clocked;
    // each way has a single synchronous read/write port with byte write enables.
    (* ram_style="block" *) reg [31:0] data0 [0:ARRAY_WORDS-1];
    (* ram_style="block" *) reg [31:0] data1 [0:ARRAY_WORDS-1];
    reg [31:0] read0, read1;

    reg saved_write;
    reg [31:0] saved_addr, saved_wdata;
    reg [2:0] saved_funct3;
    reg selected_way;
    reg [WORD_BITS-1:0] refill_index;
    reg [31:0] response_data;
    reg [31:0] refill_requested_word;
    reg response_error;
    reg lookahead_valid;
    reg [31:0] lookahead_addr;
    reg invalidate_pending, invalidate_seen;
    reg [SET_BITS-1:0] invalidate_index;

    wire [SET_BITS-1:0] saved_set = saved_addr[LINE_BITS+SET_BITS-1:LINE_BITS];
    wire [WORD_BITS-1:0] saved_word = saved_addr[LINE_BITS-1:2];
    wire [SET_BITS+WORD_BITS-1:0] access_index = {saved_set, saved_word};
    wire [SET_BITS+WORD_BITS-1:0] fill_index = {saved_set, refill_index};
    wire [TAG_BITS-1:0] saved_tag = saved_addr >> (LINE_BITS+SET_BITS);
    wire [31:0] line_base = saved_addr & ~(LINE_WORDS*4-1);
    wire [SET_BITS-1:0] request_set = req_addr[LINE_BITS+SET_BITS-1:LINE_BITS];
    wire [WORD_BITS-1:0] request_word = req_addr[LINE_BITS-1:2];
    wire [SET_BITS+WORD_BITS-1:0] request_index = {request_set, request_word};
    wire [TAG_BITS-1:0] request_tag = req_addr >> (LINE_BITS+SET_BITS);
    wire hit0 = valid0[request_set] && tags0[request_set] == request_tag;
    wire hit1 = valid1[request_set] && tags1[request_set] == request_tag;
    wire fresh_invalidate = (invalidate === 1'b1) && !invalidate_seen;

    wire size_bad = READ_ONLY ? (req_write || req_funct3 != 3'd2) :
                    req_write ? (req_funct3 > 3'd2) :
                    !(req_funct3==0 || req_funct3==1 || req_funct3==2 ||
                      req_funct3==4 || req_funct3==5);
    wire align_bad = ((req_funct3[1:0]==1) && req_addr[0]) ||
                     ((req_funct3[1:0]==2) && req_addr[1:0]!=0);
    wire address_bad = (req_addr >> ADDR_WIDTH) != 0;
    wire request_bad = size_bad || align_bad || address_bad;
    // A tag match alone is not enough: data must have been clocked for this
    // exact address, and invalidation always takes priority over a new reply.
    wire lookahead_hit = READ_ONLY && READ_LOOKAHEAD && !rst &&
                  state==S_IDLE && req_valid && lookahead_valid &&
                  lookahead_addr==req_addr && (hit0 || hit1) && !request_bad &&
                  !invalidate_pending && !fresh_invalidate;
    wire preview_hit = !READ_ONLY && DATA_PREVIEW && !rst &&
                  state==S_IDLE && req_valid && !req_write && lookahead_valid &&
                  lookahead_addr=={req_addr[31:2],2'b00} && (hit0 || hit1) && !request_bad &&
                  !invalidate_pending && !fresh_invalidate;
    wire launch = !rst && state==S_IDLE && req_valid &&
                  !invalidate_pending && !fresh_invalidate && !lookahead_hit && !preview_hit;
    wire lookahead_read = READ_ONLY && READ_LOOKAHEAD && !rst && req_valid &&
                  !invalidate_pending && !fresh_invalidate &&
                  (lookahead_hit || state==S_ACCESS || (state==S_RESP && !response_error));
    // Read the next EX load address on the EX->MEM edge using the same single
    // synchronous read port. Demand requests, writes and invalidation win.
    wire preview_read = !READ_ONLY && DATA_PREVIEW && !rst &&
                  (preview_valid === 1'b1) && !invalidate_pending && !fresh_invalidate &&
                  ((state==S_IDLE && (!req_valid || preview_hit)) || state==S_ACCESS ||
                   (state==S_RESP && !saved_write && !response_error));
    wire [31:0] next_read_addr=(state==S_IDLE ? req_addr : saved_addr)+32'd4;
    wire [SET_BITS+WORD_BITS-1:0] next_read_index=next_read_addr[LINE_BITS+SET_BITS-1:2];
    // One syntactic array read per way keeps synthesis from inferring separate
    // memory ports for demand, refill re-read and lookahead address choices.
    wire data_read_enable=(!rst && state==S_READ) ||
                  (launch && !request_bad && !req_write) || lookahead_read || preview_read;
    wire [SET_BITS+WORD_BITS-1:0] data_read_index=state==S_READ ? access_index :
                  launch ? request_index : preview_read ? preview_addr[LINE_BITS+SET_BITS-1:2] : next_read_index;

    wire [4:0] store_shift = {saved_addr[1:0],3'b000};
    wire [31:0] aligned_store = saved_wdata << store_shift;
    wire [3:0] byte_strobe = saved_funct3==0 ? (4'b0001 << saved_addr[1:0]) :
                             saved_funct3==1 ? (4'b0011 << saved_addr[1:0]) : 4'b1111;
    wire [31:0] selected_read = selected_way ? read1 : read0;
    wire [31:0] shifted_read = selected_read >> store_shift;
    wire [31:0] lookahead_data = hit0 ? read0 : read1;
    // The data mux is speculative; only ready qualifies a CPU response.
    // In S_IDLE a read-only cache can handshake only on lookahead_hit, which
    // already checks valid, exact address, tags, access size and invalidation.
    // Avoid routing req_valid (and upstream data-bus completion) through the
    // instruction bits and prediction target adder. Other states are unchanged.
    wire lookahead_data_select = READ_ONLY && READ_LOOKAHEAD &&
                                 state==S_IDLE && lookahead_valid;
    wire refill_complete = !rst && state==S_REFILL && bf_ready;
    wire store_complete = !rst && state==S_WRITE && bf_ready;

    function [31:0] load_value;
        input [31:0] shifted,full_word;
        input [2:0] size;
        begin
            case(size)
                0: load_value={{24{shifted[7]}},shifted[7:0]};
                1: load_value={{16{shifted[15]}},shifted[15:0]};
                2: load_value=full_word;
                4: load_value={24'b0,shifted[7:0]};
                5: load_value={16'b0,shifted[15:0]};
                default: load_value=0;
            endcase
        end
    endfunction
    // A hit performs its synchronous data read on the acceptance edge and
    // completes on the following edge: no additional lookup pipeline bubbles.
    assign ready = !rst && (state==S_RESP || state==S_ACCESS || lookahead_hit || preview_hit ||
                           (WRITE_RESPONSE_FORWARD && store_complete));
    assign error = !rst && ((state==S_RESP && response_error) ||
                           (WRITE_RESPONSE_FORWARD && store_complete && bf_error));
    assign rdata = preview_hit ? load_value(lookahead_data >> {req_addr[1:0],3'b000},lookahead_data,req_funct3) :
                   (WRITE_RESPONSE_FORWARD && store_complete) ? 32'd0 : lookahead_data_select ? lookahead_data :
                   state==S_ACCESS ? load_value(shifted_read,selected_read,saved_funct3) : response_data;
    assign busy = !rst && (state!=S_IDLE || invalidate_pending ||
                           fresh_invalidate || req_valid);
    // During a refill valid remains asserted across beats and the address
    // advances only at completion. A zero-wait backend can deliver one word
    // per cycle, with no inter-beat bubbles inserted by this controller.
    assign bf_req_valid = !rst && (state==S_REFILL || state==S_WRITE);
    assign bf_req_write = state==S_WRITE;
    assign bf_req_addr = state==S_WRITE ? saved_addr :
                         line_base + ({{(32-WORD_BITS){1'b0}},refill_index} << 2);
    assign bf_req_wdata = saved_wdata;
    assign bf_req_funct3 = state==S_WRITE ? saved_funct3 : 3'd2;

    // The mutually exclusive refill/store states share one physical write port.
    // Use one address/data/mask mux and one write assignment per byte lane so
    // the device synthesizer sees a byte-enabled RAM rather than two writers.
    wire cache_write_enable=(refill_complete || store_complete) && !bf_error;
    wire [SET_BITS+WORD_BITS-1:0] cache_write_index=refill_complete ? fill_index : access_index;
    wire [31:0] cache_write_data=refill_complete ? bf_rdata : aligned_store;
    wire [3:0] cache_write_strobe=refill_complete ? 4'b1111 : byte_strobe;
    // Separate per-way processes preserve synchronous-read RAM inference.
    always @(posedge clk) begin
        if (data_read_enable) read0 <= data0[data_read_index];
        if (cache_write_enable && !selected_way) begin
            if(cache_write_strobe[0]) data0[cache_write_index][7:0] <= cache_write_data[7:0];
            if(cache_write_strobe[1]) data0[cache_write_index][15:8] <= cache_write_data[15:8];
            if(cache_write_strobe[2]) data0[cache_write_index][23:16] <= cache_write_data[23:16];
            if(cache_write_strobe[3]) data0[cache_write_index][31:24] <= cache_write_data[31:24];
        end
    end
    always @(posedge clk) begin
        if (data_read_enable) read1 <= data1[data_read_index];
        if (cache_write_enable && selected_way) begin
            if(cache_write_strobe[0]) data1[cache_write_index][7:0] <= cache_write_data[7:0];
            if(cache_write_strobe[1]) data1[cache_write_index][15:8] <= cache_write_data[15:8];
            if(cache_write_strobe[2]) data1[cache_write_index][23:16] <= cache_write_data[23:16];
            if(cache_write_strobe[3]) data1[cache_write_index][31:24] <= cache_write_data[31:24];
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            state<=S_IDLE;
            valid0<=0; valid1<=0; lru_victim<=0;
            saved_write<=0; saved_addr<=0; saved_wdata<=0; saved_funct3<=0;
            selected_way<=0; refill_index<=0;
            response_data<=0; response_error<=0; refill_requested_word<=0;
            lookahead_valid<=0; lookahead_addr<=0;
            invalidate_pending<=0; invalidate_seen<=0; invalidate_index<=0;
            invalidate_done<=0;
            hit_count<=0; miss_count<=0; refill_word_count<=0; backend_write_count<=0;
        end else begin
            invalidate_done<=0;
            if(fresh_invalidate || invalidate_pending || state==S_INVALIDATE)
                lookahead_valid<=0;
            else if(preview_read) begin
                lookahead_valid<=1;
                lookahead_addr<={preview_addr[31:2],2'b00};
            end else if(lookahead_read) begin
                lookahead_valid<=1;
                lookahead_addr<=next_read_addr;
            end else if(launch || store_complete || refill_complete) lookahead_valid<=0;
            if (invalidate !== 1'b1) invalidate_seen<=0;
            if (fresh_invalidate) begin
                invalidate_pending<=1;
                invalidate_seen<=1;
            end
            case (state)
                S_IDLE: begin
                    if (invalidate_pending || fresh_invalidate) begin
                        invalidate_pending<=0;
                        invalidate_index<=0;
                        state<=S_INVALIDATE;
                    end else if (lookahead_hit || preview_hit) begin
                        // Completion and the next synchronous lookahead read
                        // share this edge. No new outstanding transaction.
                        hit_count<=hit_count+1'b1;
                        lru_victim[request_set]<=hit0;
                    end else if (req_valid) begin
                        saved_write<=req_write;
                        saved_addr<=req_addr;
                        saved_wdata<=req_wdata;
                        saved_funct3<=req_funct3;
                        response_error<=request_bad;
                        response_data<=0;
                        if (request_bad) state<=S_RESP;
                        else if (hit0 || hit1) begin
                            selected_way<=hit1 && !hit0;
                            hit_count<=hit_count+1'b1;
                            state<=req_write ? S_WRITE : S_ACCESS;
                        end else begin
                            // Prefer an invalid way, then the per-set LRU victim.
                            if (!valid0[request_set]) begin
                                selected_way<=0; valid0[request_set]<=0;
                            end else if (!valid1[request_set]) begin
                                selected_way<=1; valid1[request_set]<=0;
                            end else begin
                                selected_way<=lru_victim[request_set];
                                if(lru_victim[request_set]) valid1[request_set]<=0;
                                else valid0[request_set]<=0;
                            end
                            refill_index<=0;
                            miss_count<=miss_count+1'b1;
                            state<=S_REFILL;
                        end
                    end
                end
                S_READ: state<=S_ACCESS;
                S_ACCESS: if(req_valid) begin
                    lru_victim[saved_set]<=!selected_way;
                    state<=S_IDLE;
                end
                S_REFILL: if (bf_ready) begin
                    if (bf_error) begin
                        // The victim was invalidated before the first beat;
                        // a partially refilled line is never made valid.
                        response_error<=1;
                        response_data<=0;
                        state<=S_RESP;
                    end else begin
                        refill_word_count<=refill_word_count+1'b1;
                        if(refill_index==saved_word) refill_requested_word<=bf_rdata;
                        if (refill_index==LINE_WORDS-1) begin
                            if(selected_way) begin
                                tags1[saved_set]<=saved_tag; valid1[saved_set]<=1;
                            end else begin
                                tags0[saved_set]<=saved_tag; valid0[saved_set]<=1;
                            end
                            // Stores need no RMW read: the backend and cache
                            // both apply byte enables after successful write.
                            // Preserve precise refill errors by waiting for all
                            // beats, then forward the captured requested word.
                            if(!saved_write && REFILL_FORWARD) begin
                                response_data<=load_value(
                                    (refill_index==saved_word ? bf_rdata : refill_requested_word) >> store_shift,
                                    refill_index==saved_word ? bf_rdata : refill_requested_word,
                                    saved_funct3);
                                state<=S_RESP;
                            end else state<=saved_write ? S_WRITE : S_READ;
                        end else refill_index<=refill_index+1'b1;
                    end
                end
                S_WRITE: if (bf_ready) begin
                    response_error<=bf_error;
                    response_data<=0;
                    if (bf_error) begin
                        // Conservatively discard the line after any rejected
                        // backend write; no failed write updates cached bytes.
                        if(selected_way) valid1[saved_set]<=0;
                        else valid0[saved_set]<=0;
                    end else begin
                        backend_write_count<=backend_write_count+1'b1;
                        lru_victim[saved_set]<=!selected_way;
                    end
                    state<=WRITE_RESPONSE_FORWARD ? S_IDLE : S_RESP;
                end
                S_RESP: if(req_valid) begin
                    // Forwarded refill responses bypass S_ACCESS; they must
                    // still mark the newly installed line most recently used.
                    if(!response_error && !saved_write)
                        lru_victim[saved_set]<=!selected_way;
                    state<=S_IDLE;
                end
                S_INVALIDATE: begin
                    valid0[invalidate_index]<=0;
                    valid1[invalidate_index]<=0;
                    lru_victim[invalidate_index]<=0;
                    if(invalidate_index==SETS-1) begin
                        invalidate_done<=1;
                        state<=S_IDLE;
                    end else invalidate_index<=invalidate_index+1'b1;
                end
                default: state<=S_IDLE;
            endcase
        end
    end
endmodule

module cpu_clock #(
    parameter integer FB_DIV=32, OUT_DIV=27
)(input wire ref_clk, reset_n, output wire clk, locked);
    GTP_GPLL #(
        .CLKIN_FREQ(27.0), .STATIC_RATIOI(1), .STATIC_RATIOM(1),
        .STATIC_RATIOF(FB_DIV), .STATIC_DUTYF(FB_DIV),
        .STATIC_RATIO0(OUT_DIV), .STATIC_DUTY0(OUT_DIV),
        .STATIC_RATIO1(8), .STATIC_DUTY1(8),
        .STATIC_RATIO2(8), .STATIC_DUTY2(8),
        .STATIC_RATIO3(8), .STATIC_DUTY3(8),
        .STATIC_RATIO4(8), .STATIC_DUTY4(8),
        .STATIC_RATIO5(8), .STATIC_DUTY5(8),
        .STATIC_RATIO6(8), .STATIC_DUTY6(8),
        .INTERNAL_FB("CLKOUTF"), .EXTERNAL_FB("DISABLE")
    ) u_pll (
        .CLKIN1(ref_clk), .CLKIN2(1'b0), .CLKIN_SEL(1'b0), .CLKFB(1'b0),
        .CLKOUT0(clk), .LOCK(locked), .PLL_PWD(1'b0), .RST(!reset_n),
        .DPS_CLK(1'b0), .DPS_EN(1'b0), .DPS_DIR(1'b0),
        .CLKOUT0_SYN(1'b0), .CLKOUT1_SYN(1'b0), .CLKOUT2_SYN(1'b0),
        .CLKOUT3_SYN(1'b0), .CLKOUT4_SYN(1'b0), .CLKOUT5_SYN(1'b0),
        .CLKOUT6_SYN(1'b0), .CLKOUTF_SYN(1'b0),
        .APB_CLK(1'b0), .APB_RST_N(1'b0), .APB_ADDR(5'b0),
        .APB_SEL(1'b0), .APB_EN(1'b0), .APB_WRITE(1'b0), .APB_WDATA(16'b0)
    );
endmodule

module cpu_core #(parameter integer BRANCH_PREDICT=0, parameter integer BTB_INDEX_BITS=4,
                  parameter integer PRIVILEGED=0, parameter integer STORE_DATA_BYPASS=1,
                  parameter integer DIRECT_JUMP_PREDICT=0, parameter integer RETURN_PREDICT=0,
                  parameter integer ZMMUL=0) (
    input wire clk, rst,
    input wire irq_timer, irq_software, irq_external,
    output wire imem_valid,
    output wire [31:0] imem_addr,
    input wire imem_ready,
    input wire [31:0] imem_rdata,
    input wire imem_error,
    output wire dmem_valid, dmem_write,
    output wire [31:0] dmem_addr, dmem_wdata,
    output wire [2:0] dmem_funct3,
    input wire dmem_ready,
    input wire [31:0] dmem_rdata,
    input wire dmem_error,
    output wire fence_valid,
    input wire fence_ready,
    output wire fence_i_valid,
    input wire fence_i_ready,
    output reg halted,
    output reg [31:0] trap_cause, trap_pc, trap_value,
    output wire [31:0] debug_pc,
    output wire commit_valid,
    output wire [31:0] commit_pc, commit_inst,
    output wire commit_rd_we,
    output wire [4:0] commit_rd,
    output wire [31:0] commit_wdata,
    output wire redirect_valid,
    output wire [31:0] redirect_target,
    output wire dmem_preview_valid,
    output wire [31:0] dmem_preview_addr
);

    // IF：独立保存尚未应答的取指请求；跳转时标记丢弃，不能中途改地址。
    wire [31:0] pc;
    reg if_pending, if_kill;
    reg [31:0] if_req_pc;

    // IF/ID 级间寄存器：valid=0 表示气泡，不能引发任何架构副作用。
    reg id_valid, id_fetch_error, id_pred_taken;
    reg [31:0] id_pc, id_inst, id_pred_next;
    wire [4:0] id_rs1, id_rs2, id_rd, id_dec_rs1, id_dec_rs2, id_dec_rd;
    wire id_mul=ZMMUL && id_inst[6:0]==7'h33 &&
        id_inst[31:25]==7'h01 && !id_inst[14];
    wire id_csr=PRIVILEGED && id_inst[6:0]==7'h73 &&
        (id_inst[14:12]==1 || id_inst[14:12]==2 || id_inst[14:12]==3 ||
         id_inst[14:12]==5 || id_inst[14:12]==6 || id_inst[14:12]==7);
    wire id_system=PRIVILEGED && (id_inst[6:0]==7'h73 ||
        (id_inst[6:0]==7'h0f && id_inst[14:12]==1));
    assign id_rs1=id_mul ? id_inst[19:15] : id_csr ? (id_inst[14] ? 5'd0 : id_inst[19:15]) : id_dec_rs1;
    assign id_rs2=id_mul ? id_inst[24:20] : id_dec_rs2;
    assign id_rd=(id_mul || id_csr) ? id_inst[11:7] : id_dec_rd;
    wire [31:0] id_i,id_s,id_b,id_u,id_j,rf_a,rf_b;
    wire id_SLLI, id_SRLI, id_SRAI, id_ADD, id_SUB, id_SLL, id_SLT, id_SLTU, id_XOR, id_SRL, id_SRA, id_OR, id_AND, id_JALR, id_LB, id_LH, id_LW, id_LBU, id_LHU, id_ADDI, id_SLTI, id_SLTIU, id_XORI, id_ORI, id_ANDI, id_SB, id_SH, id_SW, id_BEQ, id_BNE, id_BLT, id_BGE, id_BLTU, id_BGEU, id_LUI, id_AUIPC, id_JAL, id_FENCE, id_FENCETSO, id_PAUSE, id_ECALL, id_EBREAK;
    wire [41:0] id_ctrl = {id_SLLI, id_SRLI, id_SRAI, id_ADD, id_SUB, id_SLL, id_SLT, id_SLTU, id_XOR, id_SRL, id_SRA, id_OR, id_AND, id_JALR, id_LB, id_LH, id_LW, id_LBU, id_LHU, id_ADDI, id_SLTI, id_SLTIU, id_XORI, id_ORI, id_ANDI, id_SB, id_SH, id_SW, id_BEQ, id_BNE, id_BLT, id_BGE, id_BLTU, id_BGEU, id_LUI, id_AUIPC, id_JAL, id_FENCE, id_FENCETSO, id_PAUSE, id_ECALL, id_EBREAK};
    decoder u_decoder (
        .inst(id_inst),.rs1(id_dec_rs1),.rs2(id_dec_rs2),.rd(id_dec_rd),
        .imm_i(id_i),.imm_s(id_s),.imm_b(id_b),.imm_u(id_u),.imm_j(id_j),
        .SLLI(id_SLLI),
        .SRLI(id_SRLI),
        .SRAI(id_SRAI),
        .ADD(id_ADD),
        .SUB(id_SUB),
        .SLL(id_SLL),
        .SLT(id_SLT),
        .SLTU(id_SLTU),
        .XOR(id_XOR),
        .SRL(id_SRL),
        .SRA(id_SRA),
        .OR(id_OR),
        .AND(id_AND),
        .JALR(id_JALR),
        .LB(id_LB),
        .LH(id_LH),
        .LW(id_LW),
        .LBU(id_LBU),
        .LHU(id_LHU),
        .ADDI(id_ADDI),
        .SLTI(id_SLTI),
        .SLTIU(id_SLTIU),
        .XORI(id_XORI),
        .ORI(id_ORI),
        .ANDI(id_ANDI),
        .SB(id_SB),
        .SH(id_SH),
        .SW(id_SW),
        .BEQ(id_BEQ),
        .BNE(id_BNE),
        .BLT(id_BLT),
        .BGE(id_BGE),
        .BLTU(id_BLTU),
        .BGEU(id_BGEU),
        .LUI(id_LUI),
        .AUIPC(id_AUIPC),
        .JAL(id_JAL),
        .FENCE(id_FENCE),
        .FENCETSO(id_FENCETSO),
        .PAUSE(id_PAUSE),
        .ECALL(id_ECALL),
        .EBREAK(id_EBREAK)
    );

    // ID/EX：保存操作数、控制信号和该条指令自己的 PC。
    reg ex_valid, ex_fetch_error, ex_pred_taken;
    reg [31:0] ex_pc,ex_inst,ex_a,ex_b,ex_i,ex_s,ex_bimm,ex_u,ex_j,ex_pred_next;
    reg [4:0] ex_rs1,ex_rs2,ex_rd;
    reg [41:0] ex_ctrl;
    wire SLLI, SRLI, SRAI, ADD, SUB, SLL, SLT, SLTU, XOR, SRL, SRA, OR, AND, JALR, LB, LH, LW, LBU, LHU, ADDI, SLTI, SLTIU, XORI, ORI, ANDI, SB, SH, SW, BEQ, BNE, BLT, BGE, BLTU, BGEU, LUI, AUIPC, JAL, FENCE, FENCETSO, PAUSE, ECALL, EBREAK;
    assign {SLLI, SRLI, SRAI, ADD, SUB, SLL, SLT, SLTU, XOR, SRL, SRA, OR, AND, JALR, LB, LH, LW, LBU, LHU, ADDI, SLTI, SLTIU, XORI, ORI, ANDI, SB, SH, SW, BEQ, BNE, BLT, BGE, BLTU, BGEU, LUI, AUIPC, JAL, FENCE, FENCETSO, PAUSE, ECALL, EBREAK} = ex_ctrl;

    // EX/MEM：访存等待期间保持地址、宽度、方向和 Store 数据。
    reg mem_valid,mem_load,mem_store,mem_fence,mem_writes,mem_exc;
    reg mem_csr, mem_mret, mem_wfi, mem_fence_i, mem_serial;
    reg [31:0] mem_csr_source, mem_next_pc;
    reg [31:0] mem_pc,mem_inst,mem_result,mem_addr,mem_store_data;
    reg [31:0] mem_cause,mem_tval;
    reg [4:0] mem_rd;

    // MEM/WB：统一在此写回；MEM 等待时，较早的 WB 指令仍只提交一次。
    reg wb_valid,wb_writes,wb_counter_write;
    reg [31:0] wb_pc,wb_inst,wb_result,wb_mem_rdata,wb_next_pc;
    reg [4:0] wb_rd;

    wire ex_load = LB || LH || LW || LBU || LHU;
    wire ex_mul=ZMMUL && ex_inst[6:0]==7'h33 &&
        ex_inst[31:25]==7'h01 && !ex_inst[14];
    wire ex_csr=PRIVILEGED && ex_inst[6:0]==7'h73 &&
        (ex_inst[14:12]==1 || ex_inst[14:12]==2 || ex_inst[14:12]==3 ||
         ex_inst[14:12]==5 || ex_inst[14:12]==6 || ex_inst[14:12]==7);
    wire ex_mret=PRIVILEGED && ex_inst==32'h30200073;
    wire ex_wfi=PRIVILEGED && ex_inst==32'h10500073;
    wire ex_fence_i=PRIVILEGED && ex_inst[6:0]==7'h0f && ex_inst[14:12]==1;
    wire ex_serial=PRIVILEGED && (ex_inst[6:0]==7'h73 || ex_fence_i);
    wire ex_csr_write=ex_inst[13:12]==1 || ex_inst[19:15]!=0;
    wire ex_store = SB || SH || SW;
    wire ex_mem = ex_load || ex_store;
    wire ex_fence = FENCE || FENCETSO;
    wire ex_writes = ADD || SUB || SLL || SLT || SLTU || XOR || SRL || SRA || OR || AND
        || ADDI || SLTI || SLTIU || XORI || ORI || ANDI || SLLI || SRLI || SRAI
        || LUI || AUIPC || JAL || JALR || ex_load || ex_csr || ex_mul;
    wire known = (|ex_ctrl) || ex_csr || ex_mret || ex_wfi || ex_fence_i || ex_mul;

    // 前递优先最近的写者：MEM > WB > 原操作数；Load 地址不能当前递数据。
    wire mem_forward = mem_valid && mem_writes && !mem_load && !mem_exc && mem_rd!=0;
    wire wb_forward = wb_valid && wb_writes && wb_rd!=0;
    wire [31:0] forward_a = ex_rs1==0 ? 32'd0 :
        (mem_forward && mem_rd==ex_rs1) ? mem_result :
        (wb_forward && wb_rd==ex_rs1) ? wb_result : ex_a;
    wire [31:0] forward_b = ex_rs2==0 ? 32'd0 :
        (mem_forward && mem_rd==ex_rs2) ? mem_result :
        (wb_forward && wb_rd==ex_rs2) ? wb_result : ex_b;
    // One signed 33x33 product implements all four Zmmul operations. Extending
    // an unsigned operand with zero preserves values >= 0x80000000. MUL only
    // uses bits[31:0], so zero extension is also correct for its signed inputs.
    // The product joins the existing EX/MEM register and normal forwarding;
    // no additional transaction can be started or duplicated during a stall.
    wire signed [32:0] mul_a={((ex_inst[13:12]==2'b01 || ex_inst[13:12]==2'b10) && forward_a[31]),forward_a};
    wire signed [32:0] mul_b={(ex_inst[13:12]==2'b01 && forward_b[31]),forward_b};
    wire signed [65:0] mul_product=mul_a * mul_b;
    wire [31:0] multiply_result=ex_inst[13:12]==2'b00 ? mul_product[31:0] : mul_product[63:32];
    // WB -> ID 旁路：消除同一上升沿写寄存器与读取旧值之间的冲突。
    wire [31:0] id_a = (commit_rd_we && wb_rd==id_rs1) ? wb_result : rf_a;
    wire [31:0] id_bdata = (commit_rd_we && wb_rd==id_rs2) ? wb_result : rf_b;
    wire [31:0] alu_result,alu_addr,branch_target;
    wire branch_taken;
    alu u_alu (
        .pc(ex_pc),.rdata1(forward_a),.rdata2(forward_b),
        .imm_i(ex_i),.imm_s(ex_s),.imm_b(ex_bimm),.imm_u(ex_u),.imm_j(ex_j),
        .wdata(alu_result),.mem_addr(alu_addr),
        .branch_taken(branch_taken),.branch_target(branch_target),
        .SLLI(SLLI),
        .SRLI(SRLI),
        .SRAI(SRAI),
        .ADD(ADD),
        .SUB(SUB),
        .SLL(SLL),
        .SLT(SLT),
        .SLTU(SLTU),
        .XOR(XOR),
        .SRL(SRL),
        .SRA(SRA),
        .OR(OR),
        .AND(AND),
        .JALR(JALR),
        .LB(LB),
        .LH(LH),
        .LW(LW),
        .LBU(LBU),
        .LHU(LHU),
        .ADDI(ADDI),
        .SLTI(SLTI),
        .SLTIU(SLTIU),
        .XORI(XORI),
        .ORI(ORI),
        .ANDI(ANDI),
        .SB(SB),
        .SH(SH),
        .SW(SW),
        .BEQ(BEQ),
        .BNE(BNE),
        .BLT(BLT),
        .BGE(BGE),
        .BLTU(BLTU),
        .BGEU(BGEU),
        .LUI(LUI),
        .AUIPC(AUIPC),
        .JAL(JAL),
        .FENCE(FENCE),
        .FENCETSO(FENCETSO),
        .PAUSE(PAUSE),
        .ECALL(ECALL),
        .EBREAK(EBREAK)
    );

    wire data_misaligned = ex_mem &&
        (((LH || LHU || SH) && alu_addr[0]) ||
         ((LW || SW) && alu_addr[1:0]!=0));
    wire [31:0] csr_read_data, csr_trap_vector, csr_return_pc, csr_irq_cause;
    wire csr_illegal, csr_irq_pending, csr_wake_pending;
    reg [31:0] architectural_next_pc;
    reg wfi_sleep;
    reg ex_exc;
    reg [31:0] ex_cause,ex_tval;
    always @(*) begin
        ex_exc=1'b0; ex_cause=0; ex_tval=0;
        if (ex_pc[1:0]!=0) begin ex_exc=1; ex_cause=0; ex_tval=ex_pc; end
        else if (ex_fetch_error) begin ex_exc=1; ex_cause=1; ex_tval=ex_pc; end
        else if (!known || (ex_csr && csr_illegal)) begin ex_exc=1; ex_cause=2; ex_tval=ex_inst; end
        else if (EBREAK) begin ex_exc=1; ex_cause=3; ex_tval=ex_pc; end
        else if (ECALL) begin ex_exc=1; ex_cause=11; ex_tval=0; end
        else if (branch_taken && branch_target[1:0]!=0) begin
            ex_exc=1; ex_cause=0; ex_tval=branch_target;
        end else if (data_misaligned) begin
            ex_exc=1; ex_cause=ex_store ? 6 : 4; ex_tval=alu_addr;
        end
    end

    assign dmem_valid = !rst && !halted && mem_valid && !mem_exc && (mem_load || mem_store);
    assign dmem_write = mem_store;
    assign dmem_addr = mem_addr;
    assign dmem_wdata = mem_store_data;
    assign dmem_funct3 = mem_inst[14:12];
    assign fence_valid = !rst && !halted && mem_valid && !mem_exc && (mem_fence || mem_fence_i);
    assign fence_i_valid = !rst && !halted && mem_valid && !mem_exc && mem_fence_i && fence_ready;
    wire mem_finish = !rst && !halted && mem_valid &&
        (mem_exc || (((!mem_load && !mem_store) || dmem_ready) &&
                    (!(mem_fence || mem_fence_i) || fence_ready) &&
                    (!mem_fence_i || (fence_i_ready === 1'b1))));
    wire bus_fault = dmem_valid && dmem_ready && dmem_error;
    wire trap_fire = mem_finish && (mem_exc || bus_fault);
    wire irq_drain=PRIVILEGED && csr_irq_pending;
    // Do not interrupt a started data transaction. Stop new fetches, retire all
    // already-issued instructions, and enter only at an empty pipeline boundary.
    wire irq_fire=PRIVILEGED && !rst && !halted && csr_irq_pending &&
        !id_valid && !ex_valid && !mem_valid && !wb_valid;
    wire mret_fire=mem_finish && !trap_fire && mem_mret;
    wire fence_i_fire=mem_finish && !trap_fire && mem_fence_i;
    wire wfi_fire=mem_finish && !trap_fire && mem_wfi;
    wire privileged_redirect=PRIVILEGED && (trap_fire || irq_fire || mret_fire || fence_i_fire || wfi_fire);
    wire [31:0] entry_cause=trap_fire ? (mem_exc ? mem_cause : (mem_store ? 32'd7 : 32'd5)) : csr_irq_cause;
    wire [31:0] entry_pc=trap_fire ? mem_pc : architectural_next_pc;
    wire [31:0] entry_value=trap_fire ? (mem_exc ? mem_tval : mem_addr) : 32'd0;
    wire mem_allow = !mem_valid || mem_finish;
    wire ex_fire = !rst && !halted && ex_valid && mem_allow && !trap_fire;
    // A read-only hint for the synchronous D-cache RAM. It never starts a
    // backend transaction or changes architectural state before MEM validation.
    assign dmem_preview_valid=ex_fire && !ex_exc && ex_load;
    assign dmem_preview_addr=alu_addr;
    // MEM 等待时冻结 ID；即便 EX 是气泡，也不能提前放行 load 的使用者。
    wire ex_allow = mem_allow && (!ex_valid || ex_fire);
    // Store data is not needed by the EX address adder. When only rs2 depends
    // on a load, capture the completed load directly into the store payload.
    // Address/ALU/branch dependencies retain the usual load-use bubble; there
    // is deliberately no dmem_rdata -> EX ALU combinational forwarding path.
    wire id_store_data_late=STORE_DATA_BYPASS && (id_SB || id_SH || id_SW);
    wire load_use_stall = id_valid && ex_valid && ex_load && ex_rd!=0 &&
        (id_rs1==ex_rd || (id_rs2==ex_rd && !id_store_data_late));
    wire store_load_forward=STORE_DATA_BYPASS && ex_store && mem_valid && mem_load &&
        mem_writes && !mem_exc && mem_finish && !bus_fault && mem_rd!=0 && mem_rd==ex_rs2;
    wire [31:0] store_data=store_load_forward ? dmem_rdata : forward_b;
    wire [31:0] ex_actual_next=branch_taken ? branch_target : ex_pc+32'd4;
    wire branch_redirect = ex_fire && !ex_exc &&
        (BRANCH_PREDICT ? ((ex_pred_taken != branch_taken) ||
            (ex_pred_taken && branch_taken && ex_pred_next != branch_target)) : branch_taken);
    assign redirect_valid=privileged_redirect || branch_redirect;
    assign redirect_target=privileged_redirect ?
        ((trap_fire || irq_fire) ? csr_trap_vector : mret_fire ? csr_return_pc : mem_pc+32'd4) :
        (BRANCH_PREDICT ? ex_actual_next : branch_target);
    wire serial_inflight=PRIVILEGED && ((ex_valid && ex_serial) || (mem_valid && mem_serial));
    wire serial_older_busy=id_system && (ex_valid || mem_valid || wb_valid);
    wire id_fire = !rst && !halted && id_valid && ex_allow && !load_use_stall &&
        !redirect_valid && !trap_fire && !serial_inflight && !serial_older_busy && !wfi_sleep;
    wire id_allow = !id_valid || id_fire;

    assign imem_valid = !rst && (if_pending ||
        (!halted && !redirect_valid && !trap_fire && !irq_drain && !wfi_sleep && id_allow));
    assign imem_addr = if_pending ? if_req_pc : pc;
    wire fetch_fire = imem_valid && imem_ready;
    wire fetch_keep = fetch_fire && !if_kill && !redirect_valid && !trap_fire && !halted && !irq_drain && !wfi_sleep;
    wire [31:0] csr_source=mem_csr_source;
    wire [31:0] csr_write_data=mem_inst[13:12]==1 ? csr_source :
        mem_inst[13:12]==2 ? csr_read_data | csr_source : csr_read_data & ~csr_source;
    wire mem_csr_write=mem_inst[13:12]==1 || mem_inst[19:15]!=0;
    generate if(PRIVILEGED) begin:g_machine
        machine_csr u_csr (
            .clk(clk),.rst(rst),
            .read_addr(mem_valid && mem_csr ? mem_inst[31:20] : ex_inst[31:20]),
            .read_write_intent(ex_csr && ex_csr_write),
            .read_data(csr_read_data),.illegal(csr_illegal),
            .write_valid(mem_finish && !trap_fire && mem_csr && mem_csr_write),
            .write_addr(mem_inst[31:20]),.write_data(csr_write_data),
            // A CSR write to minstret replaces its implicit increment for that
            // same instruction, although it remains visible on commit_valid.
            .retire(commit_valid && !wb_counter_write),
            .irq_timer(irq_timer),.irq_software(irq_software),.irq_external(irq_external),
            .irq_pending(csr_irq_pending),.irq_cause(csr_irq_cause),.wake_pending(csr_wake_pending),
            .trap_enter(trap_fire || irq_fire),.entry_pc(entry_pc),.entry_cause(entry_cause),.entry_value(entry_value),
            .mret(mret_fire),.trap_vector(csr_trap_vector),.return_pc(csr_return_pc)
        );
    end else begin:g_no_machine
        assign csr_read_data=0; assign csr_illegal=0; assign csr_irq_pending=0;
        assign csr_irq_cause=0; assign csr_wake_pending=0; assign csr_trap_vector=0; assign csr_return_pc=0;
    end endgenerate
    always @(posedge clk) begin
        if(rst) begin architectural_next_pc<=0; wfi_sleep<=0; end
        else begin
            if(commit_valid) architectural_next_pc<=wb_next_pc;
            if(privileged_redirect) architectural_next_pc<=redirect_target;
            if(wfi_fire) wfi_sleep<=1;
            else if(csr_wake_pending || (PRIVILEGED && (trap_fire || irq_fire || mret_fire))) wfi_sleep<=0;
        end
    end
    localparam integer BTB_ENTRIES=1<<BTB_INDEX_BITS;
    reg [BTB_ENTRIES-1:0] btb_valid;
    reg [29-BTB_INDEX_BITS:0] btb_tag[0:BTB_ENTRIES-1];
    reg [31:0] btb_target[0:BTB_ENTRIES-1];
    reg [1:0] btb_counter[0:BTB_ENTRIES-1];
    wire [BTB_INDEX_BITS-1:0] fetch_index=imem_addr[BTB_INDEX_BITS+1:2];
    wire [BTB_INDEX_BITS-1:0] train_index=ex_pc[BTB_INDEX_BITS+1:2];
    wire predict_hit=BRANCH_PREDICT && btb_valid[fetch_index] &&
        btb_tag[fetch_index]==imem_addr[31:BTB_INDEX_BITS+2];
    // Decode a completed fetched JAL directly, avoiding BTB cold/conflict misses.
    // These are prediction hints only: EX still verifies every target and flushes
    // a wrong prediction through the existing precise redirect machinery.
    wire direct_jump=BRANCH_PREDICT && DIRECT_JUMP_PREDICT && !imem_error &&
        imem_rdata[6:0]==7'h6f;
    wire [31:0] direct_target=imem_addr+
        {{11{imem_rdata[31]}},imem_rdata[31],imem_rdata[19:12],
         imem_rdata[20],imem_rdata[30:21],1'b0};
    // Update the small return stack only on resolved, non-faulting EX controls.
    // No speculative stack updates means wrong-path fetches cannot corrupt it.
    // Overflow discards the oldest hint, underflow falls back to the BTB.
    reg [31:0] return_stack[0:15];
    reg [4:0] return_count;
    wire return_hint=BRANCH_PREDICT && RETURN_PREDICT && !imem_error &&
        (imem_rdata==32'h00008067 || imem_rdata==32'h00028067) && return_count!=0;
    wire ex_link_rd=ex_rd==5'd1 || ex_rd==5'd5;
    wire ex_link_rs1=ex_rs1==5'd1 || ex_rs1==5'd5;
    wire return_push=(JAL || JALR) && ex_link_rd;
    wire return_pop=JALR && ex_link_rs1 && (!ex_link_rd || ex_rd!=ex_rs1);
    integer return_index;
    always @(posedge clk) begin
        if(rst || privileged_redirect) return_count<=0;
        else if(BRANCH_PREDICT && RETURN_PREDICT && ex_fire && !ex_exc) begin
            if(return_push && return_pop) begin
                return_stack[0]<=ex_pc+32'd4;
                if(return_count==0) return_count<=1;
            end else if(return_push) begin
                return_stack[0]<=ex_pc+32'd4;
                for(return_index=1;return_index<16;return_index=return_index+1)
                    return_stack[return_index]<=return_stack[return_index-1];
                if(return_count<16) return_count<=return_count+1'b1;
            end else if(return_pop && return_count!=0) begin
                for(return_index=0;return_index<15;return_index=return_index+1)
                    return_stack[return_index]<=return_stack[return_index+1];
                return_count<=return_count-1'b1;
            end
        end
    end
    wire predicted_taken=direct_jump || return_hint || (predict_hit && btb_counter[fetch_index][1]);
    wire [31:0] predicted_next=direct_jump ? direct_target :
        return_hint ? return_stack[0] :
        predicted_taken ? btb_target[fetch_index] : imem_addr+32'd4;
    wire predict_jump=fetch_keep && predicted_taken;
    wire ex_control=BEQ || BNE || BLT || BGE || BLTU || BGEU || JAL || JALR;
    wire train_hit=btb_valid[train_index] && btb_tag[train_index]==ex_pc[31:BTB_INDEX_BITS+2];
    always @(posedge clk) begin
        if(rst || privileged_redirect) btb_valid<=0;
        else if(BRANCH_PREDICT && ex_fire && !ex_exc && ex_control) begin
            btb_valid[train_index]<=1;
            btb_tag[train_index]<=ex_pc[31:BTB_INDEX_BITS+2];
            btb_target[train_index]<=branch_target;
            if(JAL || JALR) btb_counter[train_index]<=2'b11;
            else if(!train_hit) btb_counter[train_index]<=branch_taken ? 2'b10 : 2'b01;
            else if(branch_taken) begin
                if(btb_counter[train_index]!=2'b11) btb_counter[train_index]<=btb_counter[train_index]+1'b1;
            end else if(btb_counter[train_index]!=2'b00) btb_counter[train_index]<=btb_counter[train_index]-1'b1;
        end
    end
    pc_reg u_pc (
        .clk(clk),.rst(rst),.branch_taken(redirect_valid || predict_jump),.branch_target(redirect_valid ? redirect_target : predicted_next),
        .mem_error(halted || (trap_fire && !PRIVILEGED)),.stall(!fetch_keep && !redirect_valid),.pc(pc)
    );
    // While halted show the faulting PC, otherwise show the fetch PC.
    assign debug_pc = halted ? trap_pc : pc;
    assign commit_valid = !rst && !halted && wb_valid;
    assign commit_pc = wb_pc;
    assign commit_inst = wb_inst;
    assign commit_rd = wb_rd;
    assign commit_wdata = wb_result;
    assign commit_rd_we = commit_valid && wb_writes && wb_rd!=0;
    regfile u_regfile (
        .clk(clk),.rst(rst),.raddr1(id_rs1),.raddr2(id_rs2),.rdata1(rf_a),.rdata2(rf_b),
        .we(commit_rd_we),.waddr(wb_rd),.wdata(wb_result)
    );

    // IF transaction state is independent of pipeline flushing. Once a fetch
    // has started it stays valid until acknowledged; wrong-path data is dropped.
    always @(posedge clk) begin
        if (rst) begin if_pending<=0; if_kill<=0; if_req_pc<=0; end
        else begin
            if (imem_valid && !imem_ready && !if_pending) begin
                if_pending<=1; if_req_pc<=imem_addr; if_kill<=0;
            end
            if (if_pending && (redirect_valid || trap_fire || halted)) if_kill<=1;
            if (fetch_fire) begin if_pending<=0; if_kill<=0; end
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            id_valid<=0; id_pc<=0; id_inst<=0; id_fetch_error<=0; id_pred_next<=0; id_pred_taken<=0;
        end else if (halted || trap_fire || redirect_valid) id_valid<=0;
        else begin
            if (id_fire) id_valid<=0;
            if (fetch_keep) begin
                id_valid<=1; id_pc<=imem_addr; id_inst<=imem_rdata; id_fetch_error<=imem_error; id_pred_next<=predicted_next; id_pred_taken<=predicted_taken;
            end
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            ex_valid<=0; ex_pc<=0; ex_inst<=0; ex_fetch_error<=0; ex_pred_next<=0; ex_pred_taken<=0;
            ex_rs1<=0; ex_rs2<=0; ex_rd<=0; ex_ctrl<=0;
            ex_a<=0; ex_b<=0; ex_i<=0; ex_s<=0; ex_bimm<=0; ex_u<=0; ex_j<=0;
        end else if (halted || trap_fire || redirect_valid) ex_valid<=0;
        else begin
            if (ex_fire) ex_valid<=0;
            // EX 停顿时保存已经前递的值，避免 WB 排空后丢失操作数。
            if (ex_valid) begin ex_a<=forward_a; ex_b<=forward_b; end
            if (id_fire) begin
                ex_valid<=1; ex_pc<=id_pc; ex_inst<=id_inst; ex_fetch_error<=id_fetch_error; ex_pred_next<=id_pred_next; ex_pred_taken<=id_pred_taken;
                ex_rs1<=id_rs1; ex_rs2<=id_rs2; ex_rd<=id_rd; ex_ctrl<=id_ctrl;
                ex_a<=id_a; ex_b<=id_bdata;
                ex_i<=id_i; ex_s<=id_s; ex_bimm<=id_b; ex_u<=id_u; ex_j<=id_j;
            end
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            mem_valid<=0; mem_load<=0; mem_store<=0; mem_fence<=0; mem_writes<=0; mem_exc<=0;
            mem_csr<=0; mem_mret<=0; mem_wfi<=0; mem_fence_i<=0; mem_serial<=0;
            mem_csr_source<=0; mem_next_pc<=0;
            mem_pc<=0; mem_inst<=0; mem_result<=0; mem_addr<=0; mem_store_data<=0;
            mem_cause<=0; mem_tval<=0; mem_rd<=0;
        end else if (halted || trap_fire) mem_valid<=0;
        else begin
            if (mem_finish) mem_valid<=0;
            if (ex_fire) begin
                mem_valid<=1; mem_load<=ex_load; mem_store<=ex_store; mem_fence<=ex_fence;
                mem_csr<=ex_csr; mem_mret<=ex_mret; mem_wfi<=ex_wfi;
                mem_fence_i<=ex_fence_i; mem_serial<=ex_serial;
                mem_csr_source<=ex_inst[14] ? {27'd0,ex_inst[19:15]} : forward_a;
                mem_next_pc<=ex_actual_next;
                mem_writes<=ex_writes; mem_exc<=ex_exc; mem_cause<=ex_cause; mem_tval<=ex_tval;
                mem_pc<=ex_pc; mem_inst<=ex_inst; mem_rd<=ex_rd;
                mem_result<=ex_mul ? multiply_result : alu_result; mem_addr<=alu_addr; mem_store_data<=store_data;
            end
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            wb_valid<=0; wb_writes<=0; wb_pc<=0; wb_inst<=0; wb_rd<=0; wb_result<=0; wb_mem_rdata<=0;
            wb_next_pc<=0;
            wb_counter_write<=0;
            halted<=0; trap_pc<=0; trap_cause<=0; trap_value<=0;
        end else begin
            wb_valid<=mem_finish && !trap_fire;
            if (mem_finish && !trap_fire) begin
                wb_writes<=mem_writes; wb_pc<=mem_pc; wb_inst<=mem_inst; wb_rd<=mem_rd;
                wb_result<=mem_csr ? csr_read_data : mem_load ? dmem_rdata : mem_result;
                wb_next_pc<=mem_mret ? csr_return_pc : mem_next_pc;
                wb_counter_write<=mem_csr && mem_csr_write &&
                    (mem_inst[31:20]==12'hb02 || mem_inst[31:20]==12'hb82);
                wb_mem_rdata<=dmem_rdata;
            end
            if (trap_fire) begin
                halted<=!PRIVILEGED; trap_pc<=mem_pc;
                trap_cause<=mem_exc ? mem_cause : (mem_store ? 7 : 5);
                trap_value<=mem_exc ? mem_tval : mem_addr;
            end
            if(irq_fire) begin
                trap_pc<=architectural_next_pc; trap_cause<=csr_irq_cause; trap_value<=0;
            end
        end
    end
endmodule

module data_bus #(
    parameter integer CLK_HZ=50000000,
    parameter integer BAUD=115200,
    parameter integer RAM_ADDR_WIDTH=10,
    parameter integer SYNC_RAM=0,
    parameter integer AI_ENABLE=0,
    parameter integer UART_FIFO_DEPTH=16,
    parameter RAM_FILE=""
)(
    input wire clk, rst,
    input wire req_valid, req_write,
    input wire [31:0] req_addr, req_wdata,
    input wire [2:0] req_funct3,
    output reg req_ready,
    output reg [31:0] rsp_rdata,
    output wire rsp_error,
    output wire fence_ready,
    input wire uart_rx_i,
    output wire uart_tx_o,
    output reg [31:0] test_result,
    output wire irq_uart
);
    wire ram_select = (req_addr[31:RAM_ADDR_WIDTH]==0);
    wire data_select = (req_addr==32'h10000000);
    wire status_select = (req_addr==32'h10000004);
    wire control_select = (req_addr==32'h10000008);
    wire test_select = (req_addr==32'h1000000c);
    wire cycle_lo_select=(req_addr==32'h10000010);
    wire cycle_hi_select=(req_addr==32'h10000014);
    wire cycle_select=cycle_lo_select || cycle_hi_select;
    reg [63:0] cycle_count;
    always @(posedge clk) begin
        if(rst)cycle_count<=0;
        else cycle_count<=cycle_count+64'd1;
    end
    wire ai_select=AI_ENABLE && SYNC_RAM && req_addr>=32'h10000100 && req_addr<=32'h10000118;
    wire ai_busy,ai_error,ai_dma_en;
    wire [31:0] ai_rdata,ai_dma_addr,ai_dma_data;
    generate if(AI_ENABLE && SYNC_RAM)begin:g_ai
        int8_dot #(.ADDR_WIDTH(RAM_ADDR_WIDTH)) u_ai(
            .clk(clk),.rst(rst),.req_valid(req_valid && ai_select && req_funct3==2 && !rst),
            .req_write(req_write),.req_offset(req_addr[4:0]),.req_wdata(req_wdata),
            .rsp_rdata(ai_rdata),.rsp_error(ai_error),.busy(ai_busy),
            .dma_en(ai_dma_en),.dma_addr(ai_dma_addr),.dma_rdata(ai_dma_data));
    end else begin:g_no_ai
        assign ai_busy=0;assign ai_error=0;assign ai_rdata=0;
        assign ai_dma_en=0;assign ai_dma_addr=0;
    end endgenerate
    wire mmio_select = ai_select || data_select || status_select || control_select || test_select || cycle_select;
    wire size_valid = req_write ? (req_funct3<=3'b010) :
        (req_funct3==0 || req_funct3==1 || req_funct3==2 || req_funct3==4 || req_funct3==5);
    wire alignment_error =
        ((req_funct3[1:0]==1) && req_addr[0]) ||
        ((req_funct3[1:0]==2) && (req_addr[1:0]!=0));
    wire mmio_error = ai_error || (ai_select && req_funct3!=2) || mmio_select &&
        ((status_select && req_write) || (control_select && !req_write) ||
         (test_select && req_funct3!=3'b010) ||
         (cycle_select && (req_write || req_funct3!=3'b010)));
    wire bus_error = !size_valid || alignment_error || mmio_error ||
        (!ram_select && !mmio_select);
    wire ram_access = req_valid && ram_select && !bus_error && !rst && !(ai_busy && req_write);
    wire [31:0] ram_rdata, legacy_ram_rdata, sync_ram_rdata;
    wire ram_error, legacy_ram_error, sync_ram_error, sync_ram_ready, ram_busy;
    assign ram_rdata=SYNC_RAM ? sync_ram_rdata : legacy_ram_rdata;
    assign ram_error=SYNC_RAM ? sync_ram_error : legacy_ram_error;
    generate if(SYNC_RAM) begin: g_sync
        ram_sync #(.ADDR_WIDTH(RAM_ADDR_WIDTH),.INIT_FILE(RAM_FILE),.HAS_DMA(AI_ENABLE)) u_ram (
            .clk(clk),.rst(rst),.req_valid(ram_access),.req_write(req_write),
            .req_addr(req_addr),.req_wdata(req_wdata),.req_funct3(req_funct3),
            .ready(sync_ram_ready),.rdata(sync_ram_rdata),.error(sync_ram_error),.busy(ram_busy),
            .dma_en(ai_dma_en),.dma_addr(ai_dma_addr),.dma_rdata(ai_dma_data)
        );
    end else begin: g_no_sync
        assign sync_ram_ready=1'b1; assign sync_ram_rdata=32'b0;
        assign sync_ram_error=1'b0; assign ram_busy=1'b0; assign ai_dma_data=0;
        ram #(.ADDR_WIDTH(RAM_ADDR_WIDTH)) u_ram (
            .clk(clk), .rst(rst), .mem_addr(req_addr), .rdata2(req_wdata),
            .LB (ram_access && !req_write && req_funct3==0),
            .LH (ram_access && !req_write && req_funct3==1),
            .LW (ram_access && !req_write && req_funct3==2),
            .LBU(ram_access && !req_write && req_funct3==4),
            .LHU(ram_access && !req_write && req_funct3==5),
            .SB (ram_access && req_write && req_funct3==0),
            .SH (ram_access && req_write && req_funct3==1),
            .SW (ram_access && req_write && req_funct3==2),
            .ram_rdata(legacy_ram_rdata), .mem_error(legacy_ram_error)
        );
    end endgenerate
    assign rsp_error = req_valid && !rst && (bus_error || ram_error);
    wire tx_busy;
    wire tx_start = req_valid && req_ready && !rsp_error && !rst && req_write && data_select;
    uart_tx #(.CLK_HZ(CLK_HZ),.BAUD(BAUD)) u_tx (
        .clk(clk),.rst(rst),.start(tx_start),.data(req_wdata[7:0]),
        .tx(uart_tx_o),.busy(tx_busy)
    );
    wire [7:0] rx_byte;
    wire rx_pulse, rx_frame_error;
    uart_rx #(.CLK_HZ(CLK_HZ),.BAUD(BAUD)) u_rx (
        .clk(clk),.rst(rst),.rx(uart_rx_i),.data(rx_byte),
        .valid(rx_pulse),.frame_error(rx_frame_error)
    );
    localparam integer RX_PW=$clog2(UART_FIFO_DEPTH);
    reg [7:0] rx_fifo[0:UART_FIFO_DEPTH-1];
    reg [RX_PW-1:0] rx_read_ptr,rx_write_ptr;
    reg [RX_PW:0] rx_count;
    wire [7:0] rx_buffer=rx_fifo[rx_read_ptr];
    wire rx_pending=rx_count!=0;
    reg rx_overrun, rx_bad_frame,uart_irq_enable;
    wire rx_pop = req_valid && req_ready && !rsp_error && !rst && !req_write && data_select;
    wire clear_errors = req_valid && req_ready && !rsp_error && !rst && req_write &&
        control_select && req_wdata[0];
    wire control_write=req_valid && req_ready && !rsp_error && !rst && req_write && control_select;
    wire clear_rx=control_write && req_wdata[1];
    wire fifo_pop=rx_pop && rx_pending;
    wire fifo_push=rx_pulse && (rx_count<UART_FIFO_DEPTH || fifo_pop);
    assign irq_uart=uart_irq_enable && rx_pending;
    always @(posedge clk) begin
        if (rst) begin
            rx_read_ptr<=0;rx_write_ptr<=0;rx_count<=0;
            rx_overrun<=0; rx_bad_frame<=0; test_result<=0;uart_irq_enable<=0;
        end else begin
            if (clear_errors) begin rx_overrun<=0; rx_bad_frame<=0; end
            // SB touches only CONTROL[7:0]; preserve the IRQ bit in byte 1.
            if(control_write && req_funct3!=0) uart_irq_enable<=req_wdata[8];
            if(clear_rx) begin
                rx_read_ptr<=0;rx_write_ptr<=0;rx_count<=0;
            end else begin
                if(fifo_pop) rx_read_ptr<=rx_read_ptr+1'b1;
                if(fifo_push) begin rx_fifo[rx_write_ptr]<=rx_byte;rx_write_ptr<=rx_write_ptr+1'b1;end
                case({fifo_push,fifo_pop})
                  2'b10:rx_count<=rx_count+1'b1;
                  2'b01:rx_count<=rx_count-1'b1;
                  default:begin end
                endcase
                if(rx_pulse && !fifo_push) rx_overrun<=1;
            end
            if (rx_frame_error) rx_bad_frame<=1;
            if (req_valid && req_ready && !rsp_error && req_write && test_select)
                test_result<=req_wdata;
        end
    end
    // Stronger than the ISA requires: fences also drain the UART transmitter.
    assign fence_ready = !tx_busy && !ram_busy && !ai_busy;
    reg [31:0] mmio_word;
    always @(*) begin
        req_ready = !rst;
        if(req_valid && ram_select && !bus_error && SYNC_RAM) req_ready=sync_ram_ready;
        if (req_valid && req_write && data_select && !bus_error && tx_busy)
            req_ready=0;
        if(req_valid && ram_select && req_write && ai_busy && !bus_error) req_ready=0;
        mmio_word=0;
        if(ai_select) mmio_word=ai_rdata;
        else if (data_select) mmio_word=rx_pending ? {24'b0,rx_buffer} : 0;
        else if (status_select) mmio_word={28'b0,rx_bad_frame,rx_overrun,rx_pending,!tx_busy};
        else if (test_select) mmio_word=test_result;
        else if(cycle_lo_select)mmio_word=cycle_count[31:0];
        else if(cycle_hi_select)mmio_word=cycle_count[63:32];
        rsp_rdata=0;
        if (req_valid && !req_write && !rsp_error && !rst) begin
            if (ram_select) rsp_rdata=ram_rdata;
            else case(req_funct3)
                0: rsp_rdata={{24{mmio_word[7]}},mmio_word[7:0]};
                1: rsp_rdata={{16{mmio_word[15]}},mmio_word[15:0]};
                2: rsp_rdata=mmio_word;
                4: rsp_rdata={24'b0,mmio_word[7:0]};
                5: rsp_rdata={16'b0,mmio_word[15:0]};
                default: rsp_rdata=0;
            endcase
        end
    end
endmodule

module decoder(
input [31:0] inst,
//R 指令
output [4:0]rs1,
output [4:0]rs2,
output [4:0]rd,
output wire  SLLI,
output wire  SRLI,
output wire  SRAI,
output wire  ADD,
output wire  SUB,
output wire  SLL,
output wire  SLT,
output wire  SLTU,
output wire  XOR,
output wire  SRL,
output wire  SRA,
output wire  OR,
output wire  AND,
//I 指令
output wire  JALR,
output wire  LB,
output wire  LH,
output wire  LW,
output wire  LBU,
output wire  LHU,
output wire  ADDI,
output wire  SLTI,
output wire  SLTIU,
output wire  XORI,
output wire  ORI,
output wire  ANDI,
//S 指令
output wire  SB,
output wire  SH,
output wire  SW,
//B 指令
output wire  BEQ,
output wire  BNE,
output wire  BLT,
output wire  BGE,
output wire  BLTU,
output wire  BGEU,
//U 指令
output wire  LUI,
output wire  AUIPC,

//J 指令
output wire  JAL,
//
output wire  FENCE,
output wire  FENCETSO,
output wire  PAUSE,
output wire  ECALL,
output wire  EBREAK,
output wire [31:0] imm_i,
output wire [31:0] imm_s,
output wire [31:0] imm_b,
output wire [31:0] imm_u,
output wire [31:0] imm_j
    );
//R指令控制信号
assign SLLI=(inst[31:25]==7'b0000000&&inst[14:12]==3'b001&&inst[6:0]==7'b0010011)?1:0;
assign SRLI=(inst[31:25]==7'b0000000&&inst[14:12]==3'b101&&inst[6:0]==7'b0010011)?1:0;
assign SRAI=(inst[31:25]==7'b0100000&&inst[14:12]==3'b101&&inst[6:0]==7'b0010011)?1:0;
assign ADD=(inst[31:25]==7'b0000000&&inst[14:12]==3'b000&&inst[6:0]==7'b0110011)?1:0;
assign SUB=(inst[31:25]==7'b0100000&&inst[14:12]==3'b000&&inst[6:0]==7'b0110011)?1:0;
assign SLL=(inst[31:25]==7'b0000000&&inst[14:12]==3'b001&&inst[6:0]==7'b0110011)?1:0;
assign SLT=(inst[31:25]==7'b0000000&&inst[14:12]==3'b010&&inst[6:0]==7'b0110011)?1:0;
assign SLTU=(inst[31:25]==7'b0000000&&inst[14:12]==3'b011&&inst[6:0]==7'b0110011)?1:0;
assign XOR=(inst[31:25]==7'b0000000&&inst[14:12]==3'b100&&inst[6:0]==7'b0110011)?1:0;
assign SRL=(inst[31:25]==7'b0000000&&inst[14:12]==3'b101&&inst[6:0]==7'b0110011)?1:0;
assign SRA=(inst[31:25]==7'b0100000&&inst[14:12]==3'b101&&inst[6:0]==7'b0110011)?1:0;
assign OR=(inst[31:25]==7'b0000000&&inst[14:12]==3'b110&&inst[6:0]==7'b0110011)?1:0;
assign AND=(inst[31:25]==7'b0000000&&inst[14:12]==3'b111&&inst[6:0]==7'b0110011)?1:0;
//I指令控制信号
assign JALR=(inst[14:12]==3'b000&&inst[6:0]==7'b1100111)?1:0;
assign LB=(inst[14:12]==3'b000&&inst[6:0]==7'b0000011)?1:0;
assign LH=(inst[14:12]==3'b001&&inst[6:0]==7'b0000011)?1:0;
assign LW=(inst[14:12]==3'b010&&inst[6:0]==7'b0000011)?1:0;
assign LBU=(inst[14:12]==3'b100&&inst[6:0]==7'b0000011)?1:0;
assign LHU=(inst[14:12]==3'b101&&inst[6:0]==7'b0000011)?1:0;
assign ADDI=(inst[14:12]==3'b000&&inst[6:0]==7'b0010011)?1:0;
assign SLTI=(inst[14:12]==3'b010&&inst[6:0]==7'b0010011)?1:0;
assign SLTIU=(inst[14:12]==3'b011&&inst[6:0]==7'b0010011)?1:0;
assign XORI=(inst[14:12]==3'b100&&inst[6:0]==7'b0010011)?1:0;
assign ORI=(inst[14:12]==3'b110&&inst[6:0]==7'b0010011)?1:0;
assign ANDI=(inst[14:12]==3'b111&&inst[6:0]==7'b0010011)?1:0;
//S指令控制信号
assign SB=(inst[14:12]==3'b000&&inst[6:0]==7'b0100011)?1:0;
assign SH=(inst[14:12]==3'b001&&inst[6:0]==7'b0100011)?1:0;
assign SW=(inst[14:12]==3'b010&&inst[6:0]==7'b0100011)?1:0;
//B指令控制信号
assign BEQ=(inst[14:12]==3'b000&&inst[6:0]==7'b1100011)?1:0;
assign BNE=(inst[14:12]==3'b001&&inst[6:0]==7'b1100011)?1:0;
assign BLT=(inst[14:12]==3'b100&&inst[6:0]==7'b1100011)?1:0;
assign BGE=(inst[14:12]==3'b101&&inst[6:0]==7'b1100011)?1:0;
assign BLTU=(inst[14:12]==3'b110&&inst[6:0]==7'b1100011)?1:0;
assign BGEU=(inst[14:12]==3'b111&&inst[6:0]==7'b1100011)?1:0;
//U指令控制信号
assign LUI=(inst[6:0]==7'b0110111)?1:0;
assign AUIPC=(inst[6:0]==7'b0010111)?1:0;
//J指令控制信号
assign JAL=(inst[6:0]==7'b1101111)?1:0;
// Memory ordering / environment instructions
assign FENCE=(inst[14:12]==3'b000 && inst[6:0]==7'b0001111) && !FENCETSO && !PAUSE;
assign FENCETSO=(inst[31:0]==32'b10000011001100000000000000001111)?1:0;
assign PAUSE=(inst[31:0]==32'b00000001000000000000000000001111)?1:0;
assign ECALL=(inst[31:0]==32'b00000000000000000000000001110011)?1:0;
assign EBREAK=(inst[31:0]==32'b00000000000100000000000001110011)?1:0;
//
assign rd=(LUI|| AUIPC||JAL||JALR||LB||LH||LW||LBU||LHU||ADDI||SLTI||SLTIU||XORI||ORI||ANDI||SLLI||SRLI||SRAI||ADD||SUB||SLL||SLT||SLTU||XOR||SRL||SRA||OR||AND )?inst[11:7]:5'b00000;
assign rs1=(JALR||BEQ||BNE||BLT||BGE||BLTU||BGEU||LB||LH||LW||LBU||LHU||SB||SH||SW||ADDI||SLTI||SLTIU||XORI||ORI||ANDI||SLLI||SRLI||SRAI||ADD||SUB||SLL||SLT||SLTU||XOR||SRL||SRA||OR||AND )?inst[19:15]:5'b00000;
assign rs2=(BEQ||BNE||BLT||BGE||BLTU||BGEU||SB||SH||SW||ADD||SUB||SLL||SLT||SLTU||XOR||SRL||SRA||OR||AND)?inst[24:20]:5'b00000;

//立即数处理
// I 型：ADDI、ANDI、LW、JALR 等
assign imm_i = {{20{inst[31]}}, inst[31:20]};

// S 型：SB、SH、SW
assign imm_s = {{20{inst[31]}},inst[31:25],inst[11:7]};

// B 型：条件分支
assign imm_b = {{19{inst[31]}},inst[31],inst[7], inst[30:25],inst[11:8],1'b0};

// U 型：LUI、AUIPC
assign imm_u = { inst[31:12],12'b0};

// J 型：JAL
assign imm_j = {{11{inst[31]}}, inst[31],inst[19:12],inst[20],inst[30:21],1'b0};

endmodule

module int8_dot #(parameter integer ADDR_WIDTH=16)(
 input wire clk,rst,req_valid,req_write,
 input wire [4:0] req_offset,
 input wire [31:0] req_wdata,
 output reg [31:0] rsp_rdata,
 output wire rsp_error, busy,
 output wire dma_en,
 output wire [31:0] dma_addr,
 input wire [31:0] dma_rdata
);
 localparam IDLE=0,READ_X=1,WAIT_X=2,READ_W=3,WAIT_W=4,MAC=5;
 reg [2:0] state;
 reg done,error;
 reg [31:0] cfg_x,cfg_w,cfg_len,cfg_bias;
 reg [31:0] xptr,wptr,left;
 reg signed [31:0] accumulator,result;
 reg signed [7:0] xbyte,wbyte;
 reg [31:0] xword,wword;
 wire packed_mode=xptr[1:0]==0 && wptr[1:0]==0 && left>=4;
 wire [31:0] step=packed_mode ? 4 : 1;
 (* use_dsp="yes" *) wire signed [15:0] product=xbyte*wbyte;
 (* use_dsp="yes" *) wire signed [15:0] product1=$signed(xword[15:8])*$signed(wword[15:8]);
 (* use_dsp="yes" *) wire signed [15:0] product2=$signed(xword[23:16])*$signed(wword[23:16]);
 (* use_dsp="yes" *) wire signed [15:0] product3=$signed(xword[31:24])*$signed(wword[31:24]);
 wire signed [16:0] sum01={product[15],product}+{product1[15],product1};
 wire signed [16:0] sum23={product2[15],product2}+{product3[15],product3};
 wire signed [17:0] packed_sum={sum01[16],sum01}+{sum23[16],sum23};
 wire signed [31:0] term=packed_mode ? {{14{packed_sum[17]}},packed_sum} : {{16{product[15]}},product};
 wire signed [31:0] next_sum=accumulator+term;
 wire [32:0] xend={1'b0,cfg_x}+{1'b0,cfg_len};
 wire [32:0] wend={1'b0,cfg_w}+{1'b0,cfg_len};
 wire bad_descriptor=cfg_len==0 || cfg_len>256 ||
     xend>(33'd1<<ADDR_WIDTH) || wend>(33'd1<<ADDR_WIDTH);
 wire known=req_offset==0 || req_offset==4 || req_offset==8 ||
     req_offset==12 || req_offset==16 || req_offset==20 || req_offset==24;
 assign busy=state!=IDLE;
 assign rsp_error=req_valid && (!known ||
     (req_write && (busy || req_offset==4 || req_offset==24)) ||
     (!req_write && req_offset==0));
 assign dma_en=state==READ_X || state==READ_W;
 assign dma_addr=state==READ_W ? wptr : xptr;
 always @(*) begin
  rsp_rdata=0;
  case(req_offset)
   4:rsp_rdata={29'b0,error,done,busy};
   8:rsp_rdata=cfg_x;
   12:rsp_rdata=cfg_w;
   16:rsp_rdata=cfg_len;
   20:rsp_rdata=cfg_bias;
   24:rsp_rdata=result;
  endcase
 end
 always @(posedge clk) begin
  if(rst)begin
   state<=IDLE;done<=0;error<=0;cfg_x<=0;cfg_w<=0;cfg_len<=0;cfg_bias<=0;
   xptr<=0;wptr<=0;left<=0;accumulator<=0;result<=0;xbyte<=0;wbyte<=0;xword<=0;wword<=0;
  end else begin
   if(req_valid && req_write && !rsp_error)begin
    case(req_offset)
     8:cfg_x<=req_wdata;
     12:cfg_w<=req_wdata;
     16:cfg_len<=req_wdata;
     20:cfg_bias<=req_wdata;
     0:begin
      if(req_wdata[1])begin done<=0;error<=0;end
      if(req_wdata[0])begin
       done<=bad_descriptor;error<=bad_descriptor;
       if(!bad_descriptor)begin
        xptr<=cfg_x;wptr<=cfg_w;left<=cfg_len;
        accumulator<=cfg_bias;state<=READ_X;
       end
      end
     end
    endcase
   end
   case(state)
    READ_X:state<=WAIT_X;
    WAIT_X:begin xword<=dma_rdata;xbyte<=dma_rdata >> {xptr[1:0],3'b000};state<=READ_W;end
    READ_W:state<=WAIT_W;
    WAIT_W:begin wword<=dma_rdata;wbyte<=dma_rdata >> {wptr[1:0],3'b000};state<=MAC;end
    MAC:begin
     accumulator<=next_sum;
     if(left==step)begin result<=next_sum;done<=1;state<=IDLE;end
     else begin xptr<=xptr+step;wptr<=wptr+step;left<=left-step;state<=READ_X;end
    end
   endcase
  end
 end
endmodule

module machine_csr (
    input wire clk, rst,
    input wire [11:0] read_addr,
    input wire read_write_intent,
    output reg [31:0] read_data,
    output wire illegal,
    input wire write_valid,
    input wire [11:0] write_addr,
    input wire [31:0] write_data,
    input wire retire,
    input wire irq_timer, irq_software, irq_external,
    output wire irq_pending,
    output wire [31:0] irq_cause,
    output wire wake_pending,
    input wire trap_enter,
    input wire [31:0] entry_pc, entry_cause, entry_value,
    input wire mret,
    output wire [31:0] trap_vector,
    output wire [31:0] return_pc
);
    reg mie_global, mpie;
    reg [31:0] mie, mtvec, mscratch, mepc, mcause, mtval;
    reg msip_software;
    reg [2:0] mcountinhibit;
    reg [63:0] mcycle, minstret;
    wire sw_pending=(irq_software === 1'b1) || msip_software;
    wire timer_pending=(irq_timer === 1'b1);
    wire ext_pending=(irq_external === 1'b1);
    wire [31:0] mip_value={20'b0,ext_pending,3'b0,timer_pending,3'b0,sw_pending,3'b0};
    wire [31:0] enabled_pending=mie & mip_value;
    assign wake_pending=|enabled_pending;
    assign irq_pending=mie_global && wake_pending;
    // Standard machine external > machine software > machine timer priority.
    assign irq_cause=enabled_pending[11] ? 32'h8000000b :
                     enabled_pending[3] ? 32'h80000003 : 32'h80000007;
    assign trap_vector={mtvec[31:2],2'b00} +
        ((entry_cause[31] && mtvec[1:0]==1) ? {entry_cause[29:0],2'b00} : 32'd0);
    assign return_pc=mepc;
    reg supported;
    wire read_only=read_addr[11:10]==2'b11;
    assign illegal=!supported || (read_only && read_write_intent);
    always @(*) begin
        supported=1;
        read_data=0;
        case(read_addr)
          12'h300: read_data={19'd0,2'b11,3'd0,mpie,3'd0,mie_global,3'd0};
          12'h301: read_data=32'h40000100; // RV32I; Zicsr/Zifencei have no misa bits.
          12'h304: read_data=mie;
          12'h305: read_data=mtvec;
          12'h306: read_data=0; // mcounteren WARL zero: no lower privilege modes.
          12'h310: read_data=0; // mstatush WARL zero: no big endian extension.
          12'h320: read_data={29'd0,mcountinhibit};
          12'h340: read_data=mscratch;
          12'h341: read_data=mepc;
          12'h342: read_data=mcause;
          12'h343: read_data=mtval;
          12'h344: read_data=mip_value;
          12'hb00,12'hc00: read_data=mcycle[31:0];
          12'hb80,12'hc80: read_data=mcycle[63:32];
          12'hb02,12'hc02: read_data=minstret[31:0];
          12'hb82,12'hc82: read_data=minstret[63:32];
          12'hf11,12'hf12,12'hf13,12'hf14,12'hf15: read_data=0;
          default: begin supported=0; read_data=0; end
        endcase
    end
    always @(posedge clk) begin
        if(rst) begin
            mie_global<=0; mpie<=0; mie<=0; mtvec<=0;
            mscratch<=0; mepc<=0; mcause<=0; mtval<=0;
            msip_software<=0; mcountinhibit<=0; mcycle<=0; minstret<=0;
        end else begin
            if(!mcountinhibit[0]) mcycle<=mcycle+64'd1;
            if(retire && !mcountinhibit[2]) minstret<=minstret+64'd1;
            // Explicit writes take precedence over automatic counter increments.
            // Preserve the other half even if an increment would carry into it.
            if(write_valid) begin
                case(write_addr)
                  12'h300: begin mie_global<=write_data[3]; mpie<=write_data[7]; end
                  12'h304: mie<=write_data & 32'h00000888;
                  12'h305: mtvec<={write_data[31:2],1'b0,write_data[1:0]==1};
                  12'h320: mcountinhibit<=write_data[2:0] & 3'b101;
                  12'h340: mscratch<=write_data;
                  12'h341: mepc<={write_data[31:2],2'b00};
                  12'h342: mcause<=write_data;
                  12'h343: mtval<=write_data;
                  12'h344: msip_software<=write_data[3];
                  12'hb00: mcycle<={mcycle[63:32],write_data};
                  12'hb80: mcycle<={write_data,mcycle[31:0]};
                  12'hb02: minstret<={minstret[63:32],write_data};
                  12'hb82: minstret<={write_data,minstret[31:0]};
                  default: begin end // Supported WARL constant CSRs ignore writes.
                endcase
            end
            if(trap_enter) begin
                mpie<=mie_global; mie_global<=0;
                mepc<={entry_pc[31:2],2'b00}; mcause<=entry_cause; mtval<=entry_value;
            end else if(mret) begin mie_global<=mpie; mpie<=1; end
        end
    end
endmodule

module pc_reg (
    input  wire  clk,
    input  wire  rst,

    // 来自流水线 EX 的有效重定向
    input  wire   branch_taken,
    input  wire [31:0] branch_target,

    // 来自核心的停机/异常与取指停顿控制
    input  wire   mem_error,
    input  wire   stall, // hold fetch PC; cpu_core releases stall for a valid redirect

    output reg  [31:0] pc
);

    always @(posedge clk) begin
        // 高电平同步复位
        if (rst)
            pc <= 32'd0;

        // 访存出错：暂时停在当前指令
        else if (mem_error || stall)
            pc <= pc;

        // 条件分支成立，或者执行JAL/JALR
        else if (branch_taken)
            pc <= branch_target;

        // 普通顺序执行
        else
            pc <= pc + 32'd4;
    end

endmodule

module ram #(
    parameter integer ADDR_WIDTH = 10
)(
    input wire clk,
    input wire rst,

    // ALU计算出的字节地址
    input wire [31:0] mem_addr,

    // 寄存器堆第二读口：Store的数据来源
    input wire [31:0] rdata2,

    // Load指令
    input wire LB,
    input wire LH,
    input wire LW,
    input wire LBU,
    input wire LHU,

    // Store指令
    input wire SB,
    input wire SH,
    input wire SW,

    // 已完成字节选择和扩展的Load结果
    output reg [31:0] ram_rdata,

    // 地址越界或未对齐
    output wire mem_error
);

    // 每个数组元素32位，占4字节
    localparam integer WORD_COUNT =
        (1 << (ADDR_WIDTH - 2));

    reg [31:0] mem [0:WORD_COUNT-1];

    // 当前是否为访存指令
    wire is_load;
    wire is_store;
    wire active;

    assign is_load =LB || LH || LW || LBU || LHU;

    assign is_store =SB || SH || SW;

    assign active = is_load || is_store;

    // 字节地址拆成：字下标 + 字内字节偏移
    wire [ADDR_WIDTH-3:0] word_index;
    wire [1:0] byte_offset;
    wire [4:0] shift_bits;

    assign word_index =mem_addr[ADDR_WIDTH-1:2];
    assign byte_offset = mem_addr[1:0];

    // 字节偏移乘8，转换成比特移位量
    assign shift_bits = {byte_offset, 3'b000};

    // 检查地址范围
    wire range_ok;
    assign range_ok =
        (mem_addr[31:ADDR_WIDTH] == 0);

    // 检查自然对齐
    wire misaligned;
    assign misaligned =((LH || LHU || SH) && mem_addr[0]) || ((LW || SW) && (mem_addr[1:0] != 2'b00));
    assign mem_error =!rst && active && (!range_ok || misaligned);

    // 组合读

    reg  [31:0] read_word;
    wire [31:0] shifted_read;
    // 将目标字节/半字移动到最低位
    assign shifted_read = read_word >> shift_bits;
    always @(*) begin
        read_word = 32'b0;
        if (!rst && is_load && !mem_error)
            read_word = mem[word_index];
    end
    always @(*) begin
        ram_rdata = 32'b0;
        if (!rst && is_load && !mem_error) begin
            if (LB)
                ram_rdata ={{24{shifted_read[7]}},shifted_read[7:0]};
            else if (LH)
                ram_rdata ={{16{shifted_read[15]}},shifted_read[15:0]};
            else if (LW)
                ram_rdata = read_word;
            else if (LBU)
                ram_rdata ={24'b0, shifted_read[7:0]};
            else if (LHU)
                ram_rdata ={16'b0, shifted_read[15:0]};
        end
    end
    
    // 生成字节写使能

    reg  [3:0] write_strobe;
    wire [31:0] shifted_write;

    // 将源寄存器低位的数据移到目标字节位置
    assign shifted_write = rdata2 << shift_bits;

    always @(*) begin
        write_strobe = 4'b0000;

        if (!rst && is_store && !mem_error) begin
            if (SB)
                write_strobe =4'b0001 << byte_offset;
            else if (SH)
                write_strobe =4'b0011 << byte_offset;
            else if (SW)
                write_strobe = 4'b1111;
        end
    end
    // 时钟上升沿写入
    always @(posedge clk) begin
        if (write_strobe[0])
            mem[word_index][7:0]<= shifted_write[7:0];
        if (write_strobe[1])
            mem[word_index][15:8]<= shifted_write[15:8];
        if (write_strobe[2])
            mem[word_index][23:16]<= shifted_write[23:16];
        if (write_strobe[3])
            mem[word_index][31:24]<= shifted_write[31:24];
    end

endmodule

