   else if(PREFETCH) begin
     if(read_enable) begin cached_valid<=1; cached_addr<=read_addr; saved_error<=read_error; end
   end else begin
     if(req_valid && ready) pending<=0;
     if(launch) begin pending<=1; saved_error<=address_error; end
   end
 end
